# Test IP addresses
test_cases = [
    'http://127.0.0.1:9999/',  # Should fail with connection refused, not InvalidURL
    'http://192.168.1.1/',     # Same
]

for url in test_cases:
    try:
        r = requests.get(url, timeout=1)
        print(f'PASS: {url} - status={r.status_code}')
    except requests.exceptions.InvalidURL as e:
        print(f'FAIL: {url} - InvalidURL: {e}')
    except Exception as e:
        print(f'PASS (expected): {url} - {type(e).__name__}')"

